CREATE TABLE invoices(id UUID PRIMARY KEY,owner_user_id UUID NOT NULL,currency VARCHAR(3) NOT NULL,total NUMERIC(12,2) NOT NULL CHECK(total>=0),payment_status VARCHAR(30) NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoice_items(id UUID PRIMARY KEY,invoice_id UUID NOT NULL REFERENCES invoices(id),description VARCHAR(200) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price NUMERIC(10,2) NOT NULL CHECK(unit_price>0));
CREATE TABLE demo_payments(id UUID PRIMARY KEY,invoice_id UUID NOT NULL UNIQUE REFERENCES invoices(id),confirmed_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
